// A candidate's suite that really passes the tests the world's claim names, run through the trusted capture
// program so the emitter is fed a capture that program really produced - bytes hashed as they passed through it,
// with its own meta - rather than a capture and a meta a test assembled.
import test from 'node:test';
import assert from 'node:assert/strict';

test('the coordinator refuses a stale head', () => { assert.ok(true); });
test('the mutant that removes the stale-head guard dies', () => { assert.ok(true); });
test('the push broker retries only reads', () => { assert.ok(true); });
